const CRM_PUBLIC_KEY = "${ll}"; // the CRM's public key — safe to share
const FORM_KEY = "${s.form_key}"; // this form's own key — it can only add leads

function setup() {
  const form = FormApp.getActiveForm();
  ScriptApp.getProjectTriggers().forEach(function (t) { if (t.getHandlerFunction() === "sendToCrm") ScriptApp.deleteTrigger(t); });
  ScriptApp.newTrigger("sendToCrm").forForm(form).onFormSubmit().create();
  console.log("Done — new answers will now go to Zero CRM.");
}

function sendToCrm(e) {
  const answers = {};
  e.response.getItemResponses().forEach(function (r) { answers[r.getItem().getTitle()] = r.getResponse(); });
  const email = e.response.getRespondentEmail ? e.response.getRespondentEmail() : "";
  if (email && !Object.keys(answers).some(function (k) { return /e-?mail/i.test(k); })) answers["Email"] = email;
  const res = UrlFetchApp.fetch(CRM_URL, {
    method: "post", contentType: "application/json", muteHttpExceptions: true,
    headers: { apikey: CRM_PUBLIC_KEY },
    payload: JSON.stringify({ p_key: FORM_KEY, p_answers: answers }),
  });
  console.log(res.getResponseCode() + " " + res.getContentText());
}
